package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// setThresholdsFile 把配置路径指向一个临时文件，返回该路径，并在测试结束时恢复原值。
// content 为空字符串表示不创建文件（模拟配置缺失）。
func setThresholdsFile(t *testing.T, content string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "thresholds.json")
	if content != "" {
		if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
			t.Fatalf("写入临时配置失败: %v", err)
		}
	}
	previous := thresholdsFile
	thresholdsFile = path
	t.Cleanup(func() { thresholdsFile = previous })
	return path
}

func TestConfiguredWarehouseUsesConfiguredThreshold(t *testing.T) {
	setThresholdsFile(t, `{"chengdu": 2, "wuhan": 10}`)
	if got := LowStockThreshold("chengdu"); got != 2 {
		t.Fatalf("LowStockThreshold(chengdu) = %d, 期望 2", got)
	}
	if got := LowStockThreshold("wuhan"); got != 10 {
		t.Fatalf("LowStockThreshold(wuhan) = %d, 期望 10", got)
	}
}

func TestUnconfiguredWarehouseFallsBackToDefaultWithConfig(t *testing.T) {
	setThresholdsFile(t, `{"chengdu": 2}`)
	if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
		t.Fatalf("配置里没有的仓库应回退默认值，得到 %d", got)
	}
}

func TestMissingAndMalformedConfigFallBackToDefault(t *testing.T) {
	cases := map[string]string{
		"文件缺失": "",
		"非法JSON": `{"chengdu":`,
	}
	for name, content := range cases {
		t.Run(name, func(t *testing.T) {
			setThresholdsFile(t, content)
			if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
				t.Fatalf("%s 时应回退默认值 %d，得到 %d", name, DefaultLowStockThreshold, got)
			}
		})
	}
}

func TestConfigHotReloadsWithoutRebuild(t *testing.T) {
	path := setThresholdsFile(t, `{"chengdu": 2}`)
	if got := LowStockThreshold("chengdu"); got != 2 {
		t.Fatalf("初始配置应生效，得到 %d", got)
	}
	if err := os.WriteFile(path, []byte(`{"chengdu": 7}`), 0o600); err != nil {
		t.Fatalf("改写配置失败: %v", err)
	}
	if got := LowStockThreshold("chengdu"); got != 7 {
		t.Fatalf("改写配置后应无需重启即生效，得到 %d", got)
	}
}

func TestIsLowStockUsesConfiguredThreshold(t *testing.T) {
	setThresholdsFile(t, `{"chengdu": 3}`)
	if !IsLowStock("chengdu", 2) {
		t.Fatal("2 < 配置阈值 3，应为低库存")
	}
	if IsLowStock("chengdu", 3) {
		t.Fatal("3 == 配置阈值 3，不应为低库存（严格小于）")
	}
}

func TestLowStockWarehousesUsesPerWarehouseThresholds(t *testing.T) {
	setThresholdsFile(t, `{"chengdu": 50}`)
	got := LowStockWarehouses(map[string]int{"chengdu": 40, "wuhan": 40})
	// chengdu 阈值 50 → 40 算低；wuhan 走默认 5 → 40 不算低。
	if len(got) != 1 || got[0] != "chengdu" {
		t.Fatalf("LowStockWarehouses = %v, 期望 [chengdu]", got)
	}
}

// TestShippedConfigIsValid 验证仓库里实际交付的 config/thresholds.json 是合法 JSON，
// 且没有覆盖冻结基线声明的「未配置」仓库（否则会改变基线语义）。
func TestShippedConfigIsValid(t *testing.T) {
	data, err := os.ReadFile(filepath.Join("..", "config", "thresholds.json"))
	if err != nil {
		t.Fatalf("读取出厂配置失败: %v", err)
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		t.Fatalf("出厂配置不是合法 JSON: %v", err)
	}
	for _, warehouse := range unconfigured {
		if _, ok := thresholds[warehouse]; ok {
			t.Fatalf("出厂配置不应覆盖基线默认仓库 %q", warehouse)
		}
	}
}
