func TestThresholdsEndToEnd(t *testing.T) {
	path := setThresholdsFile(t, `{"chengdu": 2, "wuhan": 10}`)

	if got := LowStockThreshold("chengdu"); got != 2 {
		t.Fatalf("配置阈值应为 2，得到 %d", got)
